#include "routing_panels.hpp"
#include <cmath>

AudioPanel::AudioPanel(NativeChannel* channel,QSettings* settings,QString id,Translate tx,bool demo,QWidget* parent):QWidget(parent),channel_(channel),settings_(settings),prefix_("audio"+id+"/"),tx_(std::move(tx)),demo_(demo){
    setObjectName("panel");setProperty("program",id);auto* l=new QVBoxLayout(this);l->setContentsMargins(24,20,24,20);l->setSpacing(12);
    title_=new QLabel;l->addWidget(title_);auto* row=new QHBoxLayout;volumeLabel_=new QLabel;row->addWidget(volumeLabel_);volume_=new QSlider(Qt::Horizontal);volume_->setRange(0,100);volume_->setObjectName("audioVolume"+id);volume_->setValue(settings_->value(prefix_+"volume",100).toInt());row->addWidget(volume_,1);auto* value=new QLabel(QString::number(volume_->value())+" %");value->setMinimumWidth(48);row->addWidget(value);mute_=new QCheckBox;mute_->setObjectName("audioMute"+id);mute_->setChecked(settings_->value(prefix_+"mute",false).toBool());row->addWidget(mute_);l->addLayout(row);
    auto* outputRow=new QHBoxLayout;local_=new QCheckBox;local_->setObjectName("audioLocal"+id);local_->setChecked(settings_->value(prefix_+"local",true).toBool());outputRow->addWidget(local_);deviceLabel_=new QLabel;outputRow->addWidget(deviceLabel_);devices_=new QComboBox;devices_->setObjectName("audioDevice"+id);outputRow->addWidget(devices_,1);l->addLayout(outputRow);
    auto* meters=new QHBoxLayout;for(auto pair:{std::pair{"L",&left_},std::pair{"R",&right_}}){meters->addWidget(new QLabel(pair.first));*pair.second=new QProgressBar;(*pair.second)->setRange(0,100);(*pair.second)->setValue(0);(*pair.second)->setFormat("−∞ dBFS");meters->addWidget(*pair.second,1);}l->addLayout(meters);hint_=new QLabel;hint_->setWordWrap(true);l->addWidget(hint_);
    refreshDevices();if(!demo_){channel_->setMasterVolume(volume_->value()/100.0f);channel_->setAudioMuted(mute_->isChecked());channel_->setLocalAudioEnabled(local_->isChecked());channel_->setAudioDevice(settings_->value(prefix_+"device").toByteArray());}
    connect(volume_,&QSlider::valueChanged,this,[this,value](int v){value->setText(QString::number(v)+" %");if(!demo_){channel_->setMasterVolume(v/100.0f);settings_->setValue(prefix_+"volume",v);}});
    connect(mute_,&QCheckBox::toggled,this,[this](bool on){if(!demo_){channel_->setAudioMuted(on);settings_->setValue(prefix_+"mute",on);}});
    connect(local_,&QCheckBox::toggled,this,[this](bool on){if(!demo_){channel_->setLocalAudioEnabled(on);settings_->setValue(prefix_+"local",on);}});
    connect(devices_,&QComboBox::currentIndexChanged,this,[this]{if(!demo_){const auto id=devices_->currentData().toByteArray();settings_->setValue(prefix_+"device",id);channel_->setAudioDevice(id);}});
    auto* media=new QMediaDevices(this);connect(media,&QMediaDevices::audioOutputsChanged,this,[this]{refreshDevices();});connect(channel,&NativeChannel::audioMeter,this,[this](float left,float right){leftPeak_=qMax(leftPeak_,left);rightPeak_=qMax(rightPeak_,right);});
    auto* timer=new QTimer(this);timer->setInterval(80);connect(timer,&QTimer::timeout,this,[this]{auto meter=[](QProgressBar* bar,float peak){bar->setValue(qRound(qBound(0.0f,peak,1.0f)*100));bar->setFormat(peak>0.00001f?QString::number(20*std::log10(peak),'f',1)+" dBFS":"−∞ dBFS");};meter(left_,leftPeak_);meter(right_,rightPeak_);leftPeak_=rightPeak_=0;});timer->start();retranslate();
}
void AudioPanel::refreshDevices(){QSignalBlocker block(devices_);const auto selected=settings_->value(prefix_+"device").toByteArray();devices_->clear();devices_->addItem(tx_("System default"),QByteArray{});for(const auto& d:QMediaDevices::audioOutputs())devices_->addItem(d.description(),d.id());int row=devices_->findData(selected);if(row<0){devices_->addItem(tx_("Unavailable device"),selected);row=devices_->count()-1;}devices_->setCurrentIndex(row);}
void AudioPanel::retranslate(){title_->setText(tx_(property("program")=="A"?"Program A":"Program B"));volumeLabel_->setText(tx_("Master volume"));mute_->setText(tx_("Mute"));local_->setText(tx_("Local monitoring"));deviceLabel_->setText(tx_("Audio device"));hint_->setText(tx_("Master volume and mute affect local and network audio. Local monitoring can be disabled independently. Network audio: stereo, 48 kHz."));refreshDevices();}

DigitalPanel::DigitalPanel(NetworkBus* bus,QSettings* settings,QString id,Translate tx,bool demo,QWidget* parent):QWidget(parent),bus_(bus),settings_(settings),prefix_("network"+id+"/"),tx_(std::move(tx)),demo_(demo){
    setObjectName("panel");setProperty("program",id);auto* l=new QVBoxLayout(this);l->setContentsMargins(24,20,24,20);l->setSpacing(12);title_=new QLabel;l->addWidget(title_);
    auto* row=new QHBoxLayout;nameLabel_=new QLabel;row->addWidget(nameLabel_);name_=new QLineEdit(settings_->value(prefix_+"name","Mizin Playout Program "+id).toString());name_->setMaxLength(200);row->addWidget(name_,1);audio_=new QCheckBox;audio_->setChecked(settings_->value(prefix_+"audio",true).toBool());row->addWidget(audio_);l->addLayout(row);
    auto* buttons=new QHBoxLayout;ndi_=new QPushButton;omt_=new QPushButton;ndi_->setCheckable(true);omt_->setCheckable(true);buttons->addWidget(ndi_);buttons->addWidget(omt_);buttons->addStretch();l->addLayout(buttons);
    status_=new QLabel;status_->setWordWrap(true);l->addWidget(status_);hint_=new QLabel;hint_->setWordWrap(true);l->addWidget(hint_);
    if(!demo_)bus_->setAudioEnabled(audio_->isChecked());
    connect(name_,&QLineEdit::editingFinished,this,[this]{if(!demo_)settings_->setValue(prefix_+"name",name_->text());});connect(audio_,&QCheckBox::toggled,this,[this](bool on){if(!demo_){settings_->setValue(prefix_+"audio",on);bus_->setAudioEnabled(on);}});
    for(auto pair:{std::pair{ndi_,NetworkProtocol::Ndi},std::pair{omt_,NetworkProtocol::Omt}})connect(pair.first,&QPushButton::toggled,this,[this,pair](bool start){if(demo_){QSignalBlocker block(pair.first);pair.first->setChecked(false);return;}if(start){if(!bus_->start(pair.second,name_->text())){QSignalBlocker block(pair.first);pair.first->setChecked(false);}}else bus_->stop(pair.second);refresh();});
    auto* timer=new QTimer(this);timer->setInterval(500);connect(timer,&QTimer::timeout,this,[this]{refresh();});timer->start();retranslate();
}
void DigitalPanel::retranslate(){title_->setText(tx_(property("program")=="A"?"Program A":"Program B"));nameLabel_->setText(tx_("Source name"));audio_->setText(tx_("Include audio"));hint_->setText(tx_("SDR video at source size and cadence. Start each protocol manually. Both can run together; monitor outputs remain independent."));refresh();}
void DigitalPanel::refresh(){
    ndi_->setText(tx_(bus_->sender(NetworkProtocol::Ndi).running()?"Stop NDI":"Start NDI"));omt_->setText(tx_(bus_->sender(NetworkProtocol::Omt).running()?"Stop OMT":"Start OMT"));QStringList lines;
    for(auto p:{NetworkProtocol::Ndi,NetworkProtocol::Omt}){auto& sender=bus_->sender(p);const auto s=sender.statistics();const QString protocol=p==NetworkProtocol::Ndi?"NDI":"OMT";
        if(sender.running())lines<<protocol+": "+tx_("Sending · connections %1 · video %2 · audio %3").arg(s["connections"].toInt()).arg(s["video_frames"].toInt()).arg(s["audio_packets"].toInt())+"\n"+sender.address();else lines<<protocol+": "+(sender.error().isEmpty()?tx_("Stopped"):tx_(sender.error()));}
    status_->setText(lines.join("\n"));name_->setEnabled(!bus_->sender(NetworkProtocol::Ndi).running() && !bus_->sender(NetworkProtocol::Omt).running());
}
